//! ServerCapabilities — normally AUTO-GENERATED by ggen lsp-max pack.
//! Source: schema/domain.ttl + queries/capabilities.sparql
//!
//! Hand-edited as of this commit: `ggen sync` currently fails on this repo
//! ([FM-GEN-007], `TemplateSource::Pack` unimplemented in ggen 26.7.59 — a
//! ggen core bug, not specific to this project). The prior generated version
//! of this file had every field commented out and the module wasn't even
//! declared in `lib.rs`, so nothing here was ever advertised; `hover` and
//! `completion` were fully implemented in `backend.rs` but unreachable in
//! practice. Once `ggen sync` works again, regenerate from the ontology and
//! fix the underlying SPARQL query to `DISTINCT` its rows — the previous
//! generated output had duplicate entries (e.g. `semantic_tokens_provider`
//! repeated 3x), which is what a missing DISTINCT looks like.
//!
//! `text_document_sync` and `diagnostic_provider` are intentionally NOT set
//! here — `RulePackServer::server_capabilities()`'s default already supplies
//! those (the latter depends on `self.cross_file_rules()`, which isn't
//! available to a free function), and `backend.rs`'s override merges this
//! struct on top of that default via `..`.

use lsp_types_max::*;

pub fn server_capabilities() -> ServerCapabilities {
    ServerCapabilities {
        hover_provider: Some(HoverProviderCapability::Simple(true)),

        completion_provider: Some(CompletionOptions {
            trigger_characters: Some(vec!["\"".to_string(), ":".to_string()]),
            ..Default::default()
        }),

        semantic_tokens_provider: Some(SemanticTokensServerCapabilities::SemanticTokensOptions(
            SemanticTokensOptions {
                legend: crate::semantic_tokens::legend(),
                full: Some(SemanticTokensFullOptions::Bool(true)),
                range: Some(true),
                work_done_progress_options: WorkDoneProgressOptions::default(),
            },
        )),

        execute_command_provider: Some(ExecuteCommandOptions {
            commands: {
                #[allow(unused_mut)]
                let mut commands = vec!["claude-code-config/conformanceAudit".to_string()];
                #[cfg(feature = "cargo-cicd")]
                commands.push("claude-code-config/cicdStatus".to_string());
                commands
            },
            work_done_progress_options: WorkDoneProgressOptions::default(),
        }),

        // Not yet implemented — Phase 1 of the "perfect LSP" roadmap.
        // code_lens_provider: Some(/* wired in backend */),
        // inlay_hint_provider: Some(/* wired in backend */),
        // code_action_provider: Some(/* wired in backend */),
        // definition_provider: Some(/* wired in backend */),
        // document_highlight_provider: Some(/* wired in backend */),
        // document_link_provider: Some(/* wired in backend */),
        // document_symbol_provider: Some(/* wired in backend */),
        // folding_range_provider: Some(/* wired in backend */),
        // document_formatting_provider: Some(/* wired in backend */),
        // inline_value_provider: Some(/* wired in backend */),
        // linked_editing_range_provider: Some(/* wired in backend */),
        // moniker_provider: Some(/* wired in backend */),
        // call_hierarchy_provider: Some(/* wired in backend */),
        // rename_provider: Some(/* wired in backend */),
        // type_hierarchy_provider: Some(/* wired in backend */),
        // document_range_formatting_provider: Some(/* wired in backend */),
        // references_provider: Some(/* wired in backend */),
        // selection_range_provider: Some(/* wired in backend */),
        // signature_help_provider: Some(/* wired in backend */),
        // workspace_symbol_provider: Some(/* wired in backend */),
        // color_provider: Some(/* wired in backend */),
        // declaration_provider: Some(/* wired in backend */),
        // implementation_provider: Some(/* wired in backend */),
        // document_on_type_formatting_provider: Some(/* wired in backend */),
        // type_definition_provider: Some(/* wired in backend */),
        // execute_command_provider: Some(/* wired in backend */),
        ..Default::default()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn advertises_hover() {
        assert!(server_capabilities().hover_provider.is_some());
    }

    #[test]
    fn advertises_completion_with_trigger_characters() {
        let caps = server_capabilities();
        let completion = caps.completion_provider.expect("completion_provider must be Some");
        assert_eq!(
            completion.trigger_characters,
            Some(vec!["\"".to_string(), ":".to_string()])
        );
    }

    #[test]
    fn advertises_semantic_tokens_with_nonempty_legend() {
        let caps = server_capabilities();
        match caps.semantic_tokens_provider.expect("semantic_tokens_provider must be Some") {
            SemanticTokensServerCapabilities::SemanticTokensOptions(opts) => {
                assert!(!opts.legend.token_types.is_empty());
                assert_eq!(opts.full, Some(SemanticTokensFullOptions::Bool(true)));
            }
            other => panic!("expected SemanticTokensOptions, got {other:?}"),
        }
    }
}
